                jdbc.update("INSERT INTO notes (id, target_type, target_id, note_text, at)"
                        + " VALUES (?, ?, ?, ?, ?)",
                        id, note.get("targetType"),
                        ((Number) note.get("targetId")).longValue(), note.get("text"),
                        java.time.OffsetDateTime.ofInstant(
