        if (projectTags != null) {
            for (Map<String, Object> link : projectTags) {
                // The join row's own id is IDENTITY-generated; the fixture names only the pair.
                jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
